mapper.select:
select t.business_type_cd,t.business_type_cd businessTypeCd,t.is_instance,t.is_instance
isInstance,t.method,t.service_code,t.service_code serviceCode,t.retry_count,t.retry_count
retryCount,t.status_cd,t.status_cd statusCd,t.service_id,t.service_id serviceId,t.seq,t.url,t.timeout
from c_service t
where 1 =1

    and t.business_type_cd= #{businessTypeCd}


    and t.is_instance= #{isInstance}


    and t.method= #{method}


    and t.service_code= #{serviceCode}


    and t.retry_count= #{retryCount}


    and t.status_cd= #{statusCd}


    and t.service_id= #{serviceId}


    and t.seq= #{seq}


    and t.url= #{url}


    and t.timeout= #{timeout}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update c_service t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.business_type_cd= #{businessTypeCd}


    , t.is_instance= #{isInstance}


    , t.method= #{method}


    , t.service_code= #{serviceCode}


    , t.retry_count= #{retryCount}


    , t.seq= #{seq}


    , t.url= #{url}


    , t.timeout= #{timeout}

where 1=1

    and t.service_id= #{serviceId}

